impl<T: gx::Real, O: gx::Orientation> Odd<(), T, O> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t5 = x[6] * x[6];
        let t7 = x[8] * x[8];
        let t8 = x[9] * x[9];
        let t9 = x[10] * x[16];
        let t11 = x[12] * x[18];
        let t13 = x[14] * x[20];
        let t16 = x[23] * x[23];
        let t19 = x[26] * x[26];
        let t21 = x[28] * x[28];
        let t22 = x[29] * x[29];
        let t23 = x[30] * x[31];
        let t24 = x[0].mul_add(x[0], t1);
        let t25 = x[2].mul_add(x[2], t8);
        let t26 = t24 + t25;
        let t27 = x[25].mul_add(x[25], t19);
        let t28 = x[27].mul_add(x[27], t21);
        let t29 = t27 + t28;
        let t30 = t26 + t29;
        let t31 = x[3].mul_add(x[3], t5);
        let t32 = x[7].mul_add(x[7], t7);
        let t33 = t31 + t32;
        let t34 = x[22].mul_add(x[22], t16);
        let t35 = x[24].mul_add(x[24], t22);
        let t36 = t34 + t35;
        let t37 = t33 + t36;
        let t38 = t30 - t37;
        let t39 = x[13].mul_add(x[19], t13);
        let t40 = x[15].mul_add(x[21], t23);
        let t41 = t39 + t40;
        let t42 = x[4].mul_add(x[5], t9);
        let t43 = x[11].mul_add(x[17], t11);
        let t44 = t42 + t43;
        let t45 = t41 - t44;
        let t47 = t45.mul_add(T::from_i64(2), t38);
        t47
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, by Shirokov's method in `Multivector` (no closed form
    /// for `Odd` here): the inverse as a polynomial of degree 7 whose coefficients come
    /// from the scalar parts of powers (the FaddeevâLeVerrier recursion on left multiplication,
    /// 7 products in `Multivector`), then 1 NewtonâSchulz step(s) (docs/design.md, ADR-037). `x` is scaled to its largest
    /// coefficient first. Not finite where `x` has no inverse.
    #[inline]
    pub fn inverse(self) -> Multivector<(), T, O>
    where
        T: gx::Real,
    {
        T::vectorize(#[inline(always)] move || {
        let mut size = T::zero();
        for c in self.c {
            size = size.max(c.abs());
        }
        let scale = size.recip();
        let mut x = Multivector::<(), T>::zero();
        x.c[1] = self.c[0] * scale;
        x.c[2] = self.c[1] * scale;
        x.c[3] = self.c[2] * scale;
        x.c[4] = self.c[3] * scale;
        x.c[5] = self.c[4] * scale;
        x.c[6] = self.c[5] * scale;
        x.c[22] = self.c[6] * scale;
        x.c[23] = self.c[7] * scale;
        x.c[24] = self.c[8] * scale;
        x.c[25] = self.c[9] * scale;
        x.c[26] = self.c[10] * scale;
        x.c[27] = self.c[11] * scale;
        x.c[28] = self.c[12] * scale;
        x.c[29] = self.c[13] * scale;
        x.c[30] = self.c[14] * scale;
        x.c[31] = self.c[15] * scale;
        x.c[32] = self.c[16] * scale;
        x.c[33] = self.c[17] * scale;
        x.c[34] = self.c[18] * scale;
        x.c[35] = self.c[19] * scale;
        x.c[36] = self.c[20] * scale;
        x.c[37] = self.c[21] * scale;
        x.c[38] = self.c[22] * scale;
        x.c[39] = self.c[23] * scale;
        x.c[40] = self.c[24] * scale;
        x.c[41] = self.c[25] * scale;
        x.c[57] = self.c[26] * scale;
        x.c[58] = self.c[27] * scale;
        x.c[59] = self.c[28] * scale;
        x.c[60] = self.c[29] * scale;
        x.c[61] = self.c[30] * scale;
        x.c[62] = self.c[31] * scale;
        let a = x;
        // Uâ = a, Câ = (N/k) â¨Uââ©â, Uâââ = a (Uâ â Câ); then aâ»Â¹ = (U_{Nâ1} â C_{Nâ1}) / C_N.
        let mut prev = a;
        let c = a.c[0] * T::from_i64(8);
        prev.c[0] = prev.c[0] - c;
        for k in 2..8i64 {
            let u = a * prev;
            let c = u.c[0] * T::from_ratio(8, k);
            prev = u;
            prev.c[0] = prev.c[0] - c;
        }
        let det = (a * prev).c[0];
        let mut y = prev.gp(det.recip());
        // NewtonâSchulz, y â y (2 â x y), squares the residual: the recursion loses digits as
        // its degree grows (to 10â»â´ at degree 32), and the step(s) restore them.
        for _ in 0..1 {
            let mut t = -(x * y);
            t.c[0] = t.c[0] + T::from_i64(2);
            y = y * t;
        }
        y.gp(scale).with_orientation()
        })
    }

    /// [`inverse`](Self::inverse), or `None` where it fails: where a coefficient of the
    /// residual `x xâ»Â¹ â 1` is above `âÎµ`, in any lane, or the inverse is not finite. (The
    /// general inverse has no Study number `x ~x` to test against `âxâÂ²`, as the closed forms'
    /// `try_inverse` does; the residual is the test of the iterative solvers.)
    #[inline]
    pub fn try_inverse(self) -> Option<Multivector<(), T, O>> {
        let y = self.inverse();
        let mut x = Multivector::<(), T>::zero();
        x.c[1] = self.c[0];
        x.c[2] = self.c[1];
        x.c[3] = self.c[2];
        x.c[4] = self.c[3];
        x.c[5] = self.c[4];
        x.c[6] = self.c[5];
        x.c[22] = self.c[6];
        x.c[23] = self.c[7];
        x.c[24] = self.c[8];
        x.c[25] = self.c[9];
        x.c[26] = self.c[10];
        x.c[27] = self.c[11];
        x.c[28] = self.c[12];
        x.c[29] = self.c[13];
        x.c[30] = self.c[14];
        x.c[31] = self.c[15];
        x.c[32] = self.c[16];
        x.c[33] = self.c[17];
        x.c[34] = self.c[18];
        x.c[35] = self.c[19];
        x.c[36] = self.c[20];
        x.c[37] = self.c[21];
        x.c[38] = self.c[22];
        x.c[39] = self.c[23];
        x.c[40] = self.c[24];
        x.c[41] = self.c[25];
        x.c[57] = self.c[26];
        x.c[58] = self.c[27];
        x.c[59] = self.c[28];
        x.c[60] = self.c[29];
        x.c[61] = self.c[30];
        x.c[62] = self.c[31];
        let y0: Multivector<(), T> = y.with_orientation();
        let mut r = (x * y0).c;
        r[0] = r[0] - T::one();
        let tol = T::epsilon().sqrt();
        if r.iter().all(|&c| T::all_lt(c.abs(), tol)) {
            Some(y).filter(gx::Extensor::is_finite)
        } else {
            None
        }
    }

}

